package os.kei.hyper.home.xposed

import os.kei.hyper.home.iconpack.NativeAppleDynamicIcon
import os.kei.hyper.home.iconpack.NativeColorOsDynamicIcon
import os.kei.hyper.home.iconpack.NativeDayNightIcon
import os.kei.hyper.home.iconpack.NativePaletteIcon

/** Compares generated bytes without parsing or admitting supplied MAML programs. */
internal object GeneratedNativeIconValidator {
  private const val PNG_LIMIT = 4L * 1024 * 1024
  private const val APPLE_PNG_LIMIT = 8L * 1024 * 1024
  private val appleClockNames = listOf(
    "hour.png", "minute.png", "second.png",
    "night_hour.png", "night_minute.png", "night_second.png",
  )
  private val clockNames = listOf(
    "clock_day_bg.png", "clock_day_hour_rectangle.png", "clock_day_minute_rectangle.png",
    "night_clock_day_bg.png", "night_clock_day_hour_rectangle.png", "night_clock_day_minute_rectangle.png",
  )

  fun validate(name: String, paths: Set<String>, read: (String, Long) -> ByteArray) {
    val root = "fancy_icons/$name/"
    validate(name, paths, paths.filterTo(HashSet()) { it.startsWith(root) }, read)
  }

  fun validate(name: String, paths: Set<String>, actualPaths: Set<String>,
    read: (String, Long) -> ByteArray) {
    val root = "fancy_icons/$name/"
    val cache = HashMap<String, ByteArray>()
    var pngLimit = PNG_LIMIT
    fun bytes(path: String) = cache.getOrPut(path) {
      require(path in paths) { "Missing generated native resource: $path" }
      val limit = if (path == "${root}manifest.xml") 64L * 1024 else pngLimit
      read(path, limit).also {
        require(it.size.toLong() <= limit) { "Oversized generated icon resource: $path" }
      }
    }
    val manifest = bytes("${root}manifest.xml")
    val appleKind = NativeAppleDynamicIcon.kindOfManifest(manifest)
    if (appleKind != null) pngLimit = APPLE_PNG_LIMIT
    val lightFallback = "res/drawable-xxhdpi/$name.png"
    val darkFallback = "nightmode/res/drawable-xxhdpi/$name.png"
    // appendNativeMonet deliberately publishes only fancy resources for an
    // authored native pair. A partial fallback tree is still an invalid export.
    val fancyOnlyPalette = appleKind == null && "${root}mask.png" in actualPaths &&
      lightFallback !in paths && darkFallback !in paths
    val light = bytes(if (fancyOnlyPalette) "${root}day.png" else lightFallback)
    val dark = if (fancyOnlyPalette && "${root}night.png" !in actualPaths) light
      else bytes(if (fancyOnlyPalette) "${root}night.png" else darkFallback)
    // Asset presence selects one fixed template; every path and byte must still match.
    val legacyExpanded = light.contentEquals(dark) && "${root}night.png" in actualPaths
    fun matches(canonical: Map<String, ByteArray>): Boolean {
      val expected = canonical.filterKeys { it.startsWith(root) }
      return actualPaths == expected.keys && expected.all { (path, value) ->
        bytes(path).contentEquals(value)
      }
    }
    if (appleKind != null) {
      // Snapshots need not equal blank calendar backgrounds or bare clock dials.
      // The exact manifest selects this bounded resource schema before legacy
      // generators apply their unchanged 512-pixel/4-MiB limits.
      val assets = linkedMapOf(
        "day.png" to bytes("${root}day.png"), "night.png" to bytes("${root}night.png"),
        "fallback.png" to light, "fallback-night.png" to dark,
      )
      if (appleKind == NativeAppleDynamicIcon.Kind.CLOCK) {
        for (leaf in appleClockNames) assets[leaf] = bytes("$root$leaf")
      }
      // Exact classification already proved the appearance variant. Its resource
      // schema is unchanged, so avoid copying every PNG for six trial exports.
      val canonical = NativeAppleDynamicIcon.entries(name, appleKind, assets)
      require(matches(canonical + ("${root}manifest.xml" to manifest))) {
        "Incomplete or noncanonical generated Apple icon resources: $name"
      }
      return
    }
    if ("${root}mask.png" in actualPaths) {
      require(listOf(false, true).any { legacyScalar ->
        matches(NativePaletteIcon.entries(name, light, dark,
          bytes("${root}mask.png"), bytes("${root}bg.png"), legacyExpanded = legacyExpanded,
          legacyScalarBinders = legacyScalar))
      }) {
        "Incomplete or noncanonical generated palette icon: $name"
      }
      return
    }
    if (matches(NativeDayNightIcon.entries(name, light, dark, legacyExpanded = legacyExpanded))) return

    val kind = if (clockNames.any { "$root$it" in actualPaths }) NativeColorOsDynamicIcon.Kind.CLOCK
      else NativeColorOsDynamicIcon.Kind.CALENDAR
    // Ordinary PNGs may be rendered snapshots; live backgrounds remain separate assets.
    val assets = linkedMapOf(
      "day.png" to bytes("${root}day.png"), "night.png" to bytes("${root}night.png"),
      "fallback.png" to light, "fallback-night.png" to dark,
    )
    if (kind == NativeColorOsDynamicIcon.Kind.CLOCK) {
      for (leaf in clockNames) assets[leaf] = bytes("$root$leaf")
    }
    for (fixedDark in listOf(null, false, true)) for (dim in listOf(false, true)) {
      if (matches(NativeColorOsDynamicIcon.entries(name, kind, assets, fixedDark, dim))) return
    }
    error("Incomplete or noncanonical generated icon resources: $name")
  }
}
